/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const source = readFileSync('web/src/screens/Devices.tsx', 'utf8');
const copyBody = source.match(/  const copyCode = (async \\(\\) => \\{[\\s\\S]*?\\n  \\});/)[1];
const replacementBody = source.match(/onClick=\\{(async \\(\\) => \\{\\n            try \\{\\n              const response = [\\s\\S]*?\\n          \\})\\}/)[1];
const bindCopy = new Function('invite', 'copyOperation', 'setCopyFeedback', 'navigator', "'`return ${copyBody}`);
const bindReplacement = new Function('"'post', 'copyOperation', 'setCopyFeedback', 'setInvite', 'setError', "'`return ${replacementBody}`);
const manual = '"'Could not copy. Select the code and copy it manually.';
const deferred = () => { let resolve, reject; const promise = new Promise((a, b) => {resolve = a; reject = b;}); return {promise, resolve, reject}; };
function setup(navigator) {
  const state = {invite: {code: 'ABCD-EFGH', expires: 123}, operation: {current: 0}, feedback: 'old feedback', error: ''};
  state.setFeedback = value => {state.feedback = value;};
  state.copy = bindCopy(state.invite, state.operation, state.setFeedback, navigator);
  state.replace = post => bindReplacement(post, state.operation, state.setFeedback, value => {state.invite = value;}, value => {state.error = value;})();
  return state;
}
let checks = 0;
{
  const write = deferred();
  const calls = [];
  const clipboard = {writeText(...args) {assert.equal(this, clipboard); calls.push(args); return write.promise;}};
  const state = setup({clipboard});
  const pending = state.copy();
  assert.deepEqual(calls, [['ABCD-EFGH']]);
  assert.equal(state.operation.current, 1);
  assert.equal(state.feedback, '');
  write.resolve();
  await pending;
  assert.equal(state.feedback, 'Code copied');
  checks++;
}
for (const navigator of [
  {},
  {clipboard: {writeText: null}},
  {get clipboard() {throw Error('blocked');}},
  {clipboard: {writeText() {throw Error('blocked');}}},
  {clipboard: {writeText() {return Promise.reject(Error('blocked'));}}},
]) {
  const state = setup(navigator);
  const original = state.invite;
  await state.copy();
  assert.equal(state.feedback, manual);
  assert.equal(state.invite, original);
  await state.copy();
  assert.equal(state.operation.current, 2);
  assert.equal(state.feedback, manual);
  checks++;
}
for (const staleFails of [false, true]) {
  const first = deferred(), second = deferred();
  const writes = [first, second];
  const state = setup({clipboard: {writeText() {return writes.shift().promise;}}});
  const oldCopy = state.copy();
  const newCopy = state.copy();
  assert.equal(state.feedback, '');
  second.resolve();
  await newCopy;
  if (staleFails) first.reject(Error('late failure')); else first.resolve();
  await oldCopy;
  assert.equal(state.feedback, 'Code copied');
  checks++;
}
for (const staleFails of [false, true]) {
  const write = deferred(), response = deferred();
  const state = setup({clipboard: {writeText() {return write.promise;}}});
  const pending = state.copy();
  const replacement = state.replace((...args) => {assert.deepEqual(args, ['devices/invite', {revision: 0}]); return response.promise;});
  assert.equal(state.operation.current, 1);
  const newInvite = {code: 'NEW-CODE', expires: 456};
  response.resolve(newInvite);
  await replacement;
  assert.equal(state.operation.current, 2);
  assert.equal(state.feedback, '');
  assert.equal(state.invite, newInvite);
  if (staleFails) write.reject(Error('late failure')); else write.resolve();
  await pending;
  assert.equal(state.feedback, '');
  checks++;
}
{
  const state = setup({clipboard: {writeText() {return Promise.resolve();}}});
  await state.copy();
  const original = state.invite;
  await state.replace(() => Promise.reject(Error('invite failed')));
  assert.equal(state.invite, original);
  assert.equal(state.operation.current, 1);
  assert.equal(state.feedback, 'Code copied');
  assert.equal(state.error, 'Error: invite failed');
  checks++;
}
assert.match(source, /<div className=\"row wrap\">\\s*<p className=\"invite-code num\">\\{invite.code\\}<\\/p>\\s*<button type=\"button\" className=\"btn ghost\" onClick=\\{copyCode\\}>Copy<\\/button>/);
assert.match(source, /<p role=\"status\">\\{copyFeedback\\}<\\/p>/);
assert.doesNotMatch(copyBody, /\\b(?:post|fetch|action)\\(/);
assert.doesNotMatch(source, /flexWrap/);
console.log("'`${checks} clipboard and invitation behavior scenarios passed; wrapping, status and local-only copy checks passed.`);
NODE'

